import * as React from "react"
import { Link } from "gatsby"
import Header from "../Header"
import * as s from "./Auth.module.css"

/**
 * The frame every account screen sits in.
 *
 * One card, centred, nothing else on the page. Sign-in screens that carry the
 * full site navigation invite people to wander off mid-task, and this is the
 * shortest task on the site.
 */
const AuthShell = ({ title, lead, children, footer, notice }) => (
  <>
    <Header />
    <main className={s.page} data-print="hide">
      <div className="container">
        <div className={s.card}>
          <h1 className={s.title}>{title}</h1>
          {lead ? <p className={s.lead}>{lead}</p> : null}
          {notice ? <div className={s.notice}>{notice}</div> : null}
          {children}
        </div>
        {footer ? <p className={s.footer}>{footer}</p> : null}
      </div>
    </main>
  </>
)

export const AuthLink = ({ to, children }) => (
  <Link to={to} className={s.link}>
    {children}
  </Link>
)

export default AuthShell
